//! The HTTP twin's Rust core: an imported OpenAPI contract's reference
//! model, generated by LawSpec, behind HTTP/1.1, with LawTwin's control plane
//! on an admin port (docs/reference/http-twin.md, docs/reference/http-core.md).
//!
//! The core is a registry of compiled contracts (`contracts`); it serves the
//! one it is started with. ref:DEC-http-contract-registry

pub mod admin;
pub mod clock;
pub mod contracts;
pub mod faults;
pub mod force;
pub mod history;
pub mod laws;
pub mod model;
pub mod server;
pub mod twin;

pub use lawtwin_wire::V;
pub use twin::{Config, Twin};

use std::sync::Arc;

/// Runs the twin until the process ends: the API and the admin API.
pub fn run(config: Config) -> anyhow::Result<()> {
    let contract = contracts::find(&config.contract).ok_or_else(|| {
        anyhow::anyhow!(
            "no compiled contract {}; this core serves {}",
            config.contract,
            contracts::registry().iter().map(|c| c.name).collect::<Vec<_>>().join(", ")
        )
    })?;
    let twin = Arc::new(Twin::new(contract, config.clone()).map_err(anyhow::Error::msg)?);
    let runtime = tokio::runtime::Builder::new_multi_thread().enable_all().build()?;
    runtime.block_on(async move {
        let api = tokio::net::TcpListener::bind(&config.listen).await?;
        let admin = tokio::net::TcpListener::bind(&config.admin_listen).await?;
        eprintln!(
            "lawtwin-http: {} ({}) on http://{}, admin API on http://{}, seed {}",
            contract.package,
            contract.name,
            api.local_addr()?,
            admin.local_addr()?,
            config.seed
        );
        let router = admin::router(twin.clone());
        tokio::spawn(async move {
            let _ = axum::serve(admin, router).await;
        });
        tokio::select! {
            _ = server::serve(api, twin) => {}
            _ = tokio::signal::ctrl_c() => {}
        }
        Ok(())
    })
}
